const axis = params.axis === "x" ? "x" : "y";
const axisLabel = params.axisLabel ?? "";
const props = params;

const values = Object.fromEntries(
  Object.entries(data).map(([k, row]) => [k, row[axisLabel]]),
);

const width = containerWidth || 400;
const height = 220;
const entries = Object.entries(values);
const isHorizontal = axis === "x";
const colorProp = props?.color ?? props?.colors;
const barColors = entries.map(([label], index) => {
  if (typeof colorProp === "string") {
    return colorProp;
  }

  if (Array.isArray(colorProp) && colorProp.length > 0) {
    return colorProp[index % colorProp.length];
  }

  if (colorProp && typeof colorProp === "object" && !Array.isArray(colorProp)) {
    return colorProp[label] ?? d3.schemeTableau10[index % d3.schemeTableau10.length];
  }

  return d3.schemeTableau10[index % d3.schemeTableau10.length];
});

// Wraps an axis tick label onto multiple lines, breaking only on word
// boundaries, once it would otherwise overflow its allotted width - long
// scenario names (e.g. "Culvert widened") were overlapping their neighbors
// as a single unbroken line.
function wrapAxisLabels(selection, maxWidth) {
  selection.each(function () {
    const text = d3.select(this);
    const words = text.text().split(/\s+/).filter(Boolean).reverse();
    const y = text.attr("y");
    const x = text.attr("x") ?? 0;
    const dy = parseFloat(text.attr("dy") || "0");
    let line = [];
    let lineNumber = 0;
    const lineHeight = 1.1;
    let tspan = text
      .text(null)
      .append("tspan")
      .attr("x", x)
      .attr("y", y)
      .attr("dy", `${dy}em`);
    let word = words.pop();
    while (word) {
      line.push(word);
      tspan.text(line.join(" "));
      if (tspan.node().getComputedTextLength() > maxWidth && line.length > 1) {
        line.pop();
        tspan.text(line.join(" "));
        line = [word];
        lineNumber += 1;
        tspan = text
          .append("tspan")
          .attr("x", x)
          .attr("y", y)
          .attr("dy", `${lineNumber * lineHeight + dy}em`);
        tspan.text(word);
      }
      word = words.pop();
    }
  });
}

const margin = isHorizontal
  ? { top: 20, right: 10, bottom: 50, left: 110 }
  : { top: 20, right: 0, bottom: 64, left: 80 };
const innerWidth = width - margin.left - margin.right;
const innerHeight = height - margin.top - margin.bottom;

const svg = d3.select(container).append("svg").attr("width", width).attr("height", height);

const g = svg
  .append("g")
  .attr("transform", `translate(${margin.left},${margin.top})`);

if (isHorizontal) {
  const x = d3
    .scaleLinear()
    .domain([0, d3.max(entries, ([, v]) => v) ?? 0])
    .nice()
    .range([0, innerWidth]);

  const y = d3
    .scaleBand()
    .domain(entries.map(([k]) => k))
    .range([0, innerHeight])
    .padding(0.35);

  g.selectAll("rect")
    .data(entries)
    .enter()
    .append("rect")
    .attr("x", 0)
    .attr("y", ([k]) => y(k) ?? 0)
    .attr("width", ([, v]) => x(v))
    .attr("height", y.bandwidth())
    .attr("fill", (_d, i) => barColors[i])
    .attr("rx", 4)
    .attr("ry", 4);

  g.append("g")
    .attr("transform", `translate(0,${innerHeight})`)
    .call(d3.axisBottom(x).ticks(3))
    .selectAll("text")
    .style("font-size", "15px")
    .style("font-family", "Inter, sans-serif");

  g.append("g")
    .call(d3.axisLeft(y))
    .selectAll("text")
    .style("font-size", "15px")
    .style("font-family", "Inter, sans-serif")
    .call(wrapAxisLabels, margin.left - 12);

  svg
    .append("text")
    .attr("x", width / 2 + 30)
    .attr("y", height - 10)
    .attr("text-anchor", "middle")
    .style("font-size", "16px")
    .style("font-family", "Inter, sans-serif")
    .text(props?.labelX ?? `${axisLabel} ${props?.unit ?? ""}`.trim());

  return;
}

const x = d3
  .scaleBand()
  .domain(entries.map(([k]) => k))
  .range([0, innerWidth])
  .padding(0.35);

const y = d3
  .scaleLinear()
  .domain([0, d3.max(entries, ([, v]) => v) ?? 0])
  .nice()
  .range([innerHeight, 0]);

g.selectAll("rect")
  .data(entries)
  .enter()
  .append("rect")
  .attr("x", ([k]) => x(k) ?? 0)
  .attr("y", ([, v]) => y(v))
  .attr("width", x.bandwidth())
  .attr("height", ([, v]) => innerHeight - y(v))
  .attr("fill", (_d, i) => barColors[i])
  .attr("rx", 4)
  .attr("ry", 4);

g.append("g")
  .attr("transform", `translate(0,${innerHeight})`)
  .call(d3.axisBottom(x))
  .selectAll("text")
  .style("font-size", "15px")
  .style("font-family", "Inter, sans-serif")
  .call(wrapAxisLabels, x.bandwidth());

g.append("g")
  .call(d3.axisLeft(y).ticks(3))
  .selectAll("text")
  .style("font-size", "15px")
  .style("font-family", "Inter, sans-serif");

g.append("text")
  .attr("transform", "rotate(-90)")
  .attr("y", -60)
  .attr("x", -height / 2.5)
  .attr("text-anchor", "middle")
  .style("font-size", "15px")
  .style("font-family", "Inter, sans-serif")
  .text(props?.labelY ?? `${axisLabel} ${props?.unit ?? ""}`.trim());

